import sys
import heapq

def main():
    import sys
    import heapq
    from collections import deque

    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:]))

    def build_max_heap(arr):
        return [-x for x in arr]

    def heap_pop_max(heap):
        return -heapq.heappop(heap)

    def max_beauty(heap, size):
        if size == 1:
            return heap_pop_max(heap)
        else:
            half_size = size // 2
            sub_heap = []
            for _ in range(4 * half_size * half_size):
                sub_heap.append(heap_pop_max(heap))
            sub_heaps = [sub_heap[i * half_size * half_size:(i + 1) * half_size * half_size] for i in range(4)]
            max_val = heap_pop_max(heap)
            sub_beauties = [max_beauty(sub_heap, half_size) for sub_heap in sub_heaps]
            return max_val + sum(sub_beauties)

    a_heap = build_max_heap(a)
    heapq.heapify(a_heap)
    result = max_beauty(a_heap, int(n ** 0.5))
    print(result)

if __name__ == "__main__":
    main()
